/*
 * Blog content for /blog/[slug]. Hand-written (not generated by scripts/convert.mjs).
 *
 * Rockwall site (October 31, 2026): the previous location's posts (two client articles, the pressure-mapping post and the agency's
 * two October 2026 guides) were written for that store — its city, its climate copy, its showroom — and were not
 * carried over. POSTS and POSTS_ES are empty on purpose: /blog and /es/blog render the "New articles coming soon" empty
 * state (components/blog/pages.tsx), the header's Blog item is a plain link (lib/blog-nav.ts), and the sitemap lists no
 * post. The static export refuses a dynamic route with no params, so the post routes (app/(en)/blog/[slug]/page.tsx and
 * app/es/blog/[slug]/page.tsx) were removed with the posts; restore them from the initial import commit together with the
 * first Rockwall article (and its Spanish twin in POSTS_ES; a post whose slug differs per language sets altSlug and
 * lib/blog-nav.ts BLOG_SLUG_ES) — components/blog/pages.tsx still carries PostPage and postMetadata for them.
 *
 * Inline links use [text](href) inside a paragraph — rendered by components/blog/Rich.tsx.
 */

import type { BlogImage } from './blog-images';
export type { BlogImage };

/** a data table inside a section: scrolls horizontally on narrow screens */
export type BlogTable = { caption?: string; head: string[]; rows: string[][]; note?: string };
/** the store block after the FAQ: heading, lines (inline links allowed), fine print */
export type BlogVisit = { heading: string; lines: string[]; fine?: string };

export type BlogSection = {
  heading?: string; // rendered as <h2>; the intro has none
  paragraphs: string[];
  table?: BlogTable; // rendered after the paragraphs, before the image
  image?: BlogImage & { caption?: string }; // supporting image shown after the section
};

export type BlogFaq = { question: string; answer: string };
export type BlogSource = { label: string; href: string }; // cited source, rendered under the article

export type BlogPost = {
  slug: string;
  /** the slug of the same post in the other language when it differs; undefined = same slug */
  altSlug?: string;
  title: string; // <h1> + BlogPosting.headline
  metaTitle: string; // < 60 chars
  metaDescription: string; // < 160 chars
  keywords: string[];
  datePublished: string; // ISO date
  dateModified?: string; // ISO date of the last content refresh (BlogPosting.dateModified, og:modified_time, sitemap lastmod)
  dateDisplay: string; // as given by the client
  readTime: string; // as given by the client
  featured: BlogImage;
  featuredFit?: 'contain'; // show the whole featured image instead of cropping it to the banner height
  excerpt: string; // first sentence of the post, verbatim — used on cards
  sections: BlogSection[];
  faqs: BlogFaq[];
  visit?: BlogVisit; // store block between the FAQ and the sources
  sources?: BlogSource[]; // "Sources" list after the FAQ
};

import { IMG } from './blog-images';
export { IMG };

/** English posts: none yet for the Rockwall store (NEEDS CLIENT INPUT). */
export const POSTS: BlogPost[] = [];

/** Spanish posts: none yet (keep parallel to POSTS). */
export const POSTS_ES: BlogPost[] = [];

export type BlogLocale = 'en' | 'es';
export const postsFor = (locale: BlogLocale = 'en') => (locale === 'es' ? POSTS_ES : POSTS);
export const getPost = (slug: string, locale: BlogLocale = 'en') => postsFor(locale).find((p) => p.slug === slug);
/** the three newest other posts (empty while the blog has none) */
export const relatedPosts = (slug: string, locale: BlogLocale = 'en') =>
  [...postsFor(locale)].filter((p) => p.slug !== slug).sort((a, b) => (a.datePublished < b.datePublished ? 1 : -1)).slice(0, 3);
/** the post's path in the other language (its altSlug when the slug differs per language) */
export const altBlogPath = (post: BlogPost) => `/blog/${post.altSlug || post.slug}`;
